import AppKit

final class Doc: NSDocument {
    override class func canConcurrentlyReadDocuments(ofType typeName: String) -> Bool { true }
    override func read(from url: URL, ofType typeName: String) throws {
        print("read on main thread:", Thread.isMainThread)
        let jsonURL = url.appendingPathComponent("project.json")
        let wrapper = try FileWrapper(url: jsonURL, options: .immediate)
        print("wrapper isDirectory:", wrapper.isDirectory, "isRegularFile:", wrapper.isRegularFile,
              "isSymbolicLink:", wrapper.isSymbolicLink)
        guard let data = wrapper.regularFileContents,
              let text = String(data: data, encoding: .utf8)
        else {
            throw NSError(domain: "d26", code: 1, userInfo: [
                NSLocalizedDescriptionKey: "does not contain a readable project.json."])
        }
        print("read text of", text.count)
    }
}

final class Controller: NSDocumentController {
    override var documentClassNames: [String] { ["Doc"] }
    override var defaultType: String? { "public.folder" }
    override func typeForContents(of url: URL) throws -> String { "public.folder" }
    override func documentClass(forType typeName: String) -> AnyClass? { Doc.self }
}

